// Builds the synthetic evaluation dataset and its ground-truth labels.
// Output: evaluation/dataset/* and evaluation/labels.json
// Everything here is generated by code. These are NOT real invoices and NOT real scans.

const fs = require('fs');
const path = require('path');
const { createRequire } = require('module');

// use the packages installed in backend/
const requireBackend = createRequire(path.join(__dirname, '..', 'backend', 'package.json'));
const sharp = requireBackend('sharp');
const ExcelJS = requireBackend('exceljs');

const OUT_DIR = path.join(__dirname, 'dataset');
const LABELS_FILE = path.join(__dirname, 'labels.json');

const round2 = (n) => Math.round(n * 100) / 100;
const money = (n) => n.toFixed(2);

// ---------- invoice data ----------

function makeInvoice(d) {
  const lines = d.items.map(([description, quantity, unitPrice]) => ({
    description,
    quantity,
    unitPrice,
    amount: round2(quantity * unitPrice),
  }));
  const subtotal = round2(lines.reduce((s, l) => s + l.amount, 0));
  const tax = round2(subtotal * d.taxRate);
  return {
    number: d.number,
    dateIso: d.dateIso,
    dateText: d.dateText || d.dateIso,
    supplier: d.supplier,
    customer: d.customer,
    currency: d.currency,
    taxRate: d.taxRate,
    lines,
    subtotal,
    tax,
    total: round2(subtotal + tax),
  };
}

