// ---------- text layouts ----------

function linesA(inv, opts = {}) {
  const out = ['INVOICE', `Supplier: ${inv.supplier}`];
  if (!opts.omitNumber) out.push(`Invoice No: ${inv.number}`);
  out.push(
    `Date: ${inv.dateText}`,
    `Customer: ${inv.customer}`,
    `Currency: ${inv.currency}`,
    '',
    'Description Qty Unit price Amount'
  );
  for (const l of inv.lines) {
    out.push(`${l.description} ${l.quantity} ${money(l.unitPrice)} ${money(l.amount)}`);
  }
  out.push(
    '',
    `Subtotal: ${money(inv.subtotal)}`,
    `Tax: ${money(inv.tax)}`,
    `Total (${inv.currency}): ${money(inv.total)}`
  );
  return out;
}

function linesB(inv) {
  const out = [
    'TAX INVOICE',
    `From: ${inv.supplier}`,
    `Invoice #: ${inv.number}`,
    `Issued: ${inv.dateText}`,
    `Bill to: ${inv.customer}`,
    '',
  ];
  inv.lines.forEach((l, i) => {
    out.push(`${i + 1}. ${l.description} x ${l.quantity} @ ${money(l.unitPrice)} = ${money(l.amount)}`);
  });
  out.push(
    '',
    `Net amount: ${money(inv.subtotal)}`,
    `VAT (${Math.round(inv.taxRate * 100)}%): ${money(inv.tax)}`,
    `Amount due (${inv.currency}): ${money(inv.total)}`
  );
  return out;
}

function linesC(inv) {
  const out = [
    inv.supplier,
    'Billing document',
    `Document number: ${inv.number}`,
    `Invoice date: ${inv.dateText}`,
    `Customer name: ${inv.customer}`,
    `Currency used: ${inv.currency}`,
    '',
    'Line | Description | Quantity | Price | Total',
  ];
  inv.lines.forEach((l, i) => {
    out.push(`${i + 1} | ${l.description} | ${l.quantity} | ${money(l.unitPrice)} | ${money(l.amount)}`);
  });
  out.push(
    '',
    `Sum of lines: ${money(inv.subtotal)}`,
    `Tax (${Math.round(inv.taxRate * 100)}%): ${money(inv.tax)}`,
    `Grand total: ${money(inv.total)}`
  );
  return out;
}

// ---------- PDF (tiny hand-made PDF, same idea as tests/pdfParser.test.js) ----------

function pdfEscape(text) {
  if (/[^\x20-\x7e]/.test(text)) throw new Error(`Non-ASCII text in PDF line: ${text}`);
  return text.replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
}

// pages = array of pages, each page = array of text lines
function buildPdf(pages) {
  const objs = [];
  const n = pages.length;
  objs[1] = '<< /Type /Catalog /Pages 2 0 R >>';
  const kids = pages.map((_, i) => `${4 + 2 * i} 0 R`).join(' ');
  objs[2] = `<< /Type /Pages /Kids [${kids}] /Count ${n} >>`;
  objs[3] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';
  pages.forEach((lines, i) => {
    const stream = lines
      .map((t, row) => (t === '' ? '' : `BT /F1 11 Tf 50 ${750 - row * 16} Td (${pdfEscape(t)}) Tj ET`))
      .filter(Boolean)
      .join('\n');
    objs[4 + 2 * i] =
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents ${5 + 2 * i} 0 R ` +
      '/Resources << /Font << /F1 3 0 R >> >> >>';
    objs[5 + 2 * i] = `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`;
  });

  let pdf = '%PDF-1.4\n';
  const offsets = [];
  for (let id = 1; id < objs.length; id++) {
    offsets[id] = pdf.length;
    pdf += `${id} 0 obj\n${objs[id]}\nendobj\n`;
  }
  const xrefPos = pdf.length;
  pdf += `xref\n0 ${objs.length}\n0000000000 65535 f \n`;
  for (let id = 1; id < objs.length; id++) {
    pdf += `${String(offsets[id]).padStart(10, '0')} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size ${objs.length} /Root 1 0 R >>\nstartxref\n${xrefPos}\n%%EOF\n`;
  return Buffer.from(pdf, 'latin1');
}

// ---------- CSV and XLSX ----------

function csvCell(value, delimiter) {
  const s = String(value ?? '');
  return /["\n\r]/.test(s) || s.includes(delimiter) ? `"${s.replace(/"/g, '""')}"` : s;
}

function toCsv(rows, delimiter = ',') {
  return rows.map((r) => r.map((c) => csvCell(c, delimiter)).join(delimiter)).join('\n') + '\n';
}

// key/value block, then a line item table, then the totals
function kvRows(inv, numeric = false) {
  const v = (n) => (numeric ? n : money(n));
  return [
    ['Invoice No', inv.number],
    ['Date', inv.dateIso],
    ['Supplier', inv.supplier],
    ['Customer', inv.customer],
    ['Currency', inv.currency],
    [],
    ['Description', 'Qty', 'Unit price', 'Amount'],
    ...inv.lines.map((l) => [l.description, l.quantity, v(l.unitPrice), v(l.amount)]),
    [],
    ['Subtotal', v(inv.subtotal)],
    ['Tax', v(inv.tax)],
    ['Total', v(inv.total)],
  ];
}

function flatRows(inv) {
  return [
    ['invoice_number', 'invoice_date', 'supplier', 'customer', 'currency', 'description',
      'quantity', 'unit_price', 'line_amount', 'subtotal', 'tax', 'total'],
    ...inv.lines.map((l) => [
      inv.number, inv.dateIso, inv.supplier, inv.customer, inv.currency, l.description,
      l.quantity, money(l.unitPrice), money(l.amount), money(inv.subtotal), money(inv.tax), money(inv.total),
    ]),
  ];
}

async function writeXlsx(file, sheets) {
  const wb = new ExcelJS.Workbook();
  for (const [name, rows] of sheets) {
    const ws = wb.addWorksheet(name);
    rows.forEach((r) => ws.addRow(r));
  }
  await wb.xlsx.writeFile(file);
}

// ---------- images (SVG text turned into PNG/JPG by sharp) ----------

function xmlEscape(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function svgFor(lines) {
  const width = 900;
  const lineHeight = 38;
  const height = 80 + lines.length * lineHeight;
  const texts = lines
    .map((l, i) =>
      l === ''
        ? ''
        : `<text x="40" y="${60 + i * lineHeight}" font-family="Arial, Helvetica, sans-serif" font-size="24" fill="#111111">${xmlEscape(l)}</text>`
    )
    .join('');
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}">` +
    `<rect width="100%" height="100%" fill="#ffffff"/>${texts}</svg>`
  );
}

// ---------- labels ----------

const labels = [];

function truthFields(inv) {
  return {
    invoice_number: inv.number,
    invoice_date: inv.dateIso,
    supplier_name: inv.supplier,
    customer_name: inv.customer,
    subtotal: inv.subtotal,
    tax: inv.tax,
    total: inv.total,
    currency: inv.currency,
  };
}

// expect: what a correct system should do. fields = what the document itself says.
function addLabel(file, kind, group, phase, expect, note) {
  labels.push({ file, kind, group, phase, expect, note: note || '' });
}

function okExpect(inv, extra = {}) {
  return {
    upload: 'accepted',
    status: 'completed',
    needs_review: false,
    issues: [],
    fields: truthFields(inv),
    line_item_count: inv.lines.length,
    ...extra,
  };
}

// ---------- main ----------

async function main() {
  fs.rmSync(OUT_DIR, { recursive: true, force: true });
  fs.mkdirSync(OUT_DIR, { recursive: true });
  const out = (name) => path.join(OUT_DIR, name);

  // --- digital PDFs, three layouts ---
  fs.writeFileSync(out('pdf-a-01.pdf'), buildPdf([linesA(INV.a1)]));
  addLabel('pdf-a-01.pdf', 'pdf', 'normal', 1, okExpect(INV.a1), 'layout A');
  fs.writeFileSync(out('pdf-a-02.pdf'), buildPdf([linesA(INV.a2)]));
  addLabel('pdf-a-02.pdf', 'pdf', 'normal', 1, okExpect(INV.a2), 'layout A');
  fs.writeFileSync(out('pdf-b-01.pdf'), buildPdf([linesB(INV.b1)]));
  addLabel('pdf-b-01.pdf', 'pdf', 'normal', 1, okExpect(INV.b1), 'layout B, date written as 12 Feb 2026');
  fs.writeFileSync(out('pdf-b-02.pdf'), buildPdf([linesB(INV.b2)]));
  addLabel('pdf-b-02.pdf', 'pdf', 'normal', 1, okExpect(INV.b2), 'layout B, date written as 20 Feb 2026');
  fs.writeFileSync(out('pdf-c-01.pdf'), buildPdf([linesC(INV.c1)]));
  addLabel('pdf-c-01.pdf', 'pdf', 'normal', 1, okExpect(INV.c1), 'layout C, date written as 5 March 2026');

  // --- multi-page PDF: items continue on page 2 ---
  {
    const all = linesA(INV.multi);
    const header = all.slice(0, 8);
    const itemLines = all.slice(8, 8 + INV.multi.lines.length);
    const footer = all.slice(8 + INV.multi.lines.length);
    const page1 = [...header, ...itemLines.slice(0, 8)];
    const page2 = ['Page 2 of 2', '', ...itemLines.slice(8), ...footer];
    fs.writeFileSync(out('pdf-multipage.pdf'), buildPdf([page1, page2]));
    addLabel('pdf-multipage.pdf', 'pdf', 'normal', 1, okExpect(INV.multi), '2 pages, 14 line items');
  }

  // --- not an invoice: nothing may be invented ---
  fs.writeFileSync(
    out('not-invoice.pdf'),
    buildPdf([[
      'Team meeting notes',
      'Topics: office plants, parking rules, new coffee machine',
      'Action: Sam will ask the cleaners about the kitchen',
      'Action: Priya will send the parking map to everyone',
      'Next meeting: same room, same time',
    ]])
  );
  addLabel('not-invoice.pdf', 'pdf', 'not_invoice', 1, {
    upload: 'accepted',
    status: 'completed',
    needs_review: true,
    issues: [],
    fields: {
      invoice_number: null, invoice_date: null, supplier_name: null, customer_name: null,
      subtotal: null, tax: null, total: null, currency: null,
    },
    line_item_count: 0,
  }, 'must not invent values');

  // --- CSV ---
  fs.writeFileSync(out('csv-kv-comma.csv'), toCsv(kvRows(INV.csv1), ','));
  addLabel('csv-kv-comma.csv', 'csv', 'normal', 1, okExpect(INV.csv1), 'key/value + table, comma');
  fs.writeFileSync(out('csv-kv-semicolon.csv'), toCsv(kvRows(INV.csv2), ';'));
  addLabel('csv-kv-semicolon.csv', 'csv', 'normal', 1, okExpect(INV.csv2), 'semicolon delimiter');
  fs.writeFileSync(out('csv-flat.csv'), toCsv(flatRows(INV.csv3), ','));
  addLabel('csv-flat.csv', 'csv', 'normal', 1, okExpect(INV.csv3), 'one row per line item, supplier name contains a comma');

  // --- XLSX ---
  await writeXlsx(out('xlsx-single.xlsx'), [['Invoice', kvRows(INV.x1, true)]]);
  addLabel('xlsx-single.xlsx', 'xlsx', 'normal', 1, okExpect(INV.x1), 'single sheet');
  await writeXlsx(out('xlsx-multisheet.xlsx'), [
    ['Summary', [
      ['Invoice No', INV.x2.number], ['Date', INV.x2.dateIso], ['Supplier', INV.x2.supplier],
      ['Customer', INV.x2.customer], ['Currency', INV.x2.currency],
      ['Subtotal', INV.x2.subtotal], ['Tax', INV.x2.tax], ['Total', INV.x2.total],
    ]],
    ['Items', [
      ['Description', 'Qty', 'Unit price', 'Amount'],
      ...INV.x2.lines.map((l) => [l.description, l.quantity, l.unitPrice, l.amount]),
    ]],
  ]);
  addLabel('xlsx-multisheet.xlsx', 'xlsx', 'normal', 1, okExpect(INV.x2), 'header on sheet 1, items on sheet 2');
  await writeXlsx(out('xlsx-title.xlsx'), [
    ['Sheet1', [[`${INV.x3.supplier} - Invoice`], [], ...kvRows(INV.x3, true)]],
  ]);
  addLabel('xlsx-title.xlsx', 'xlsx', 'normal', 1, okExpect(INV.x3), 'title row above the data');

  // --- images (OCR) ---
  await sharp(Buffer.from(svgFor(linesA(INV.img1)))).png().toFile(out('img-clean.png'));
  addLabel('img-clean.png', 'image', 'image', 1, okExpect(INV.img1), 'clean synthetic PNG');
  await sharp(Buffer.from(svgFor(linesB(INV.img2))))
    .rotate(2, { background: '#ffffff' })
    .resize({ width: 650 })
    .blur(0.8)
    .jpeg({ quality: 35 })
    .toFile(out('img-poor.jpg'));
  addLabel('img-poor.jpg', 'image', 'image', 1, okExpect(INV.img2), 'rotated 2 deg, blur, width 650, JPEG quality 35');
  await sharp(Buffer.from(svgFor(linesA(INV.img3))))
    .rotate(4, { background: '#ffffff' })
    .resize({ width: 480 })
    .blur(1.5)
    .jpeg({ quality: 20 })
    .toFile(out('img-very-poor.jpg'));
  addLabel('img-very-poor.jpg', 'image', 'image', 1, okExpect(INV.img3), 'rotated 4 deg, strong blur, width 480, JPEG quality 20');

  // --- deliberate errors ---
  {
    const bad = { ...INV.err1, subtotal: 100, tax: 10, total: 125 }; // 100 + 10 is not 125
    fs.writeFileSync(out('err-total-mismatch.csv'), toCsv(kvRows(bad), ','));
    addLabel('err-total-mismatch.csv', 'csv', 'error', 1, okExpect(bad, {
      needs_review: true, issues: ['total_mismatch'],
    }), 'printed total 125, but subtotal 100 + tax 10');
  }
  {
    fs.writeFileSync(out('err-missing-number.pdf'), buildPdf([linesA(INV.err2, { omitNumber: true })]));
    const expect = okExpect(INV.err2, { needs_review: true });
    expect.fields = { ...expect.fields, invoice_number: null };
    addLabel('err-missing-number.pdf', 'pdf', 'error', 1, expect, 'invoice number is not in the document');
  }
  {
    const bad = { ...INV.err3, subtotal: 100, tax: 10, total: 110 }; // lines add up to 90, not 100
    await writeXlsx(out('err-lines-mismatch.xlsx'), [['Invoice', kvRows(bad, true)]]);
    addLabel('err-lines-mismatch.xlsx', 'xlsx', 'error', 1, okExpect(bad, { needs_review: true }),
      'line items add up to 90, but subtotal says 100');
  }

  // --- corrupted and rejected files ---
  fs.writeFileSync(out('corrupt.pdf'), '%PDF-1.4\n' + 'this is damaged data, not a real pdf\n'.repeat(20));
  addLabel('corrupt.pdf', 'corrupt', 'corrupt', 1, { upload: 'accepted', status: 'failed' }, 'PDF header, damaged body');
  const pngSignature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  fs.writeFileSync(out('corrupt.png'), Buffer.concat([pngSignature, Buffer.alloc(300, 0x41)]));
  addLabel('corrupt.png', 'corrupt', 'corrupt', 1, { upload: 'accepted', status: 'failed' }, 'PNG header, damaged body');
  fs.writeFileSync(out('reject-fake.pdf'), 'this is plain text with a .pdf name');
  addLabel('reject-fake.pdf', 'rejected', 'reject', 1, { upload: 'rejected' }, 'text file pretending to be a PDF');

  // --- phase 2: duplicates and cross-document checks (uploaded one by one, in this order) ---
  fs.copyFileSync(out('csv-kv-comma.csv'), out('dup-copy-of-csv-2001.csv'));
  addLabel('dup-copy-of-csv-2001.csv', 'csv', 'duplicate', 2, okExpect(INV.csv1, {
    needs_review: true, issues: ['duplicate_file'],
  }), 'byte-identical copy of csv-kv-comma.csv');

  fs.writeFileSync(out('pair-a.pdf'), buildPdf([linesA(INV.pairA)]));
  addLabel('pair-a.pdf', 'pdf', 'pair', 2, okExpect(INV.pairA), 'first document of a matching PDF/Excel pair');
  await writeXlsx(out('pair-a.xlsx'), [['Invoice', kvRows(INV.pairA, true)]]);
  addLabel('pair-a.xlsx', 'xlsx', 'pair', 2, okExpect(INV.pairA, {
    needs_review: true, issues: ['duplicate_invoice'],
  }), 'same invoice and same values as pair-a.pdf');

  fs.writeFileSync(out('pair-b.pdf'), buildPdf([linesA(INV.pairB)]));
  addLabel('pair-b.pdf', 'pdf', 'pair', 2, okExpect(INV.pairB), 'first document of a PDF/Excel pair with different totals');
  await writeXlsx(out('pair-b.xlsx'), [['Invoice', kvRows(INV.pairBOther, true)]]);
  addLabel('pair-b.xlsx', 'xlsx', 'pair', 2, okExpect(INV.pairBOther, {
    needs_review: true, issues: ['cross_document_mismatch'],
  }), 'same invoice number as pair-b.pdf, but a different total');

  fs.writeFileSync(LABELS_FILE, JSON.stringify(labels, null, 2) + '\n');

  console.log(`Wrote ${labels.length} files to ${OUT_DIR}`);
  const counts = {};
  for (const l of labels) counts[l.kind] = (counts[l.kind] || 0) + 1;
  console.log('By kind:', JSON.stringify(counts));
  console.log(`Labels written to ${LABELS_FILE}`);
}

main().catch((err) => {
  console.error('Dataset generation failed:', err.message);
  process.exit(1);
});